tool_schemas.implementation:
def send_message(bot_id, chat_id=None, telegram_chat_id=None, text=None, parse_mode=None, reply_to_telegram_message_id=None, request_correlation_id=None, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0135000" if __import__("os").path.isdir("./environment_mix/0135000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started_ts = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ulid26():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        out = list(reversed(out))
        for _ in range(16):
            out.append(alphabet[random.getrandbits(5)])
        return "".join(out)

    def _new_id(prefix):
        return prefix + _ulid26()

    def _finish(inv_row, tool_invocations, ok_body=None, err=None, related_message_id=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        inv_row["finished_at"] = finished
        inv_row["duration_ms"] = max(0, int(round((time.time() - started_ts) * 1000)))
        inv_row["updated_at"] = finished
        inv_row["related_message_id"] = related_message_id
        if err is None:
            inv_row["status"] = "succeeded"
            inv_row["response_body"] = ok_body
            inv_row["error_code"] = None
            inv_row["error_message"] = None
        else:
            inv_row["status"] = "failed"
            inv_row["response_body"] = None
            inv_row["error_code"] = err["error"]["code"]
            inv_row["error_message"] = err["error"]["message"]
        tool_invocations.append(inv_row)
        _save("tool_invocations.json", tool_invocations)
        return ok_body if err is None else err

    bots = _load("bots.json")
    chats = _load("chats.json")
    messages = _load("messages.json")
    tool_invocations = _load("tool_invocations.json")

    inv_row = {
        "id": _new_id("tg_inv_"),
        "bot_id": bot_id if isinstance(bot_id, str) else "",
        "tool_name": "send_message",
        "request_params": {
            "bot_id": bot_id,
            "chat_id": chat_id,
            "telegram_chat_id": telegram_chat_id,
            "text": text,
            "parse_mode": parse_mode,
            "reply_to_telegram_message_id": reply_to_telegram_message_id,
            "request_correlation_id": request_correlation_id,
        },
        "response_body": None,
        "error_code": None,
        "error_message": None,
        "related_message_id": None,
        "related_update_id": None,
        "status": "failed",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    try:
        # Validate inputs
        if not isinstance(bot_id, str) or not re.match(r"^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$", bot_id):
            return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "bot_id is required and must match ^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$"))
        if not isinstance(text, str) or text == "":
            return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "text is required and must be a non-empty string"))
        if chat_id is None and telegram_chat_id is None:
            return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "Either chat_id or telegram_chat_id must be provided"))
        if chat_id is not None and (not isinstance(chat_id, str) or not re.match(r"^tg_cht_[0-9A-HJKMNP-TV-Z]{26}$", chat_id)):
            return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "chat_id must match ^tg_cht_[0-9A-HJKMNP-TV-Z]{26}$"))
        if telegram_chat_id is not None and not isinstance(telegram_chat_id, int):
            return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "telegram_chat_id must be an integer"))
        if parse_mode is not None:
            if not isinstance(parse_mode, str) or parse_mode not in ("Markdown", "MarkdownV2", "HTML"):
                return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "parse_mode must be one of ['Markdown','MarkdownV2','HTML']"))
        if reply_to_telegram_message_id is not None and not isinstance(reply_to_telegram_message_id, int):
            return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "reply_to_telegram_message_id must be an integer"))
        if request_correlation_id is not None and not isinstance(request_correlation_id, str):
            return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "request_correlation_id must be a string"))

        # Bot must exist
        bot = next((b for b in bots if b.get("id") == bot_id), None)
        if not bot:
            return _finish(inv_row, tool_invocations, err=_err("NOT_FOUND", "bot not found"))
        # Bot must be able to send
        if bot.get("status") in ("disabled", "revoked"):
            code = "bot_disabled" if bot.get("status") == "disabled" else "bot_revoked"
            return _finish(inv_row, tool_invocations, err=_err("UNAUTHORIZED", f"Bot status {bot.get('status')}; outbound send blocked", vendor_code=code, rule="Bots with status='disabled' or 'revoked' MUST NOT send messages"))

        # Idempotency by request_correlation_id (unique per bot)
        if request_correlation_id:
            existing = next((m for m in messages if m.get("bot_id") == bot_id and m.get("request_correlation_id") == request_correlation_id), None)
            if existing:
                # Return original message result (do not duplicate)
                return _finish(inv_row, tool_invocations, ok_body=existing, related_message_id=existing.get("id"))

        # Resolve / ensure chat
        resolved_chat = None
        if chat_id is not None:
            c = next((x for x in chats if x.get("id") == chat_id), None)
            if not c:
                return _finish(inv_row, tool_invocations, err=_err("NOT_FOUND", "chat_id not found"))
            if c.get("bot_id") != bot_id:
                # If telegram_chat_id provided and matches a chat for this bot, use it (relax overly-strict check)
                if telegram_chat_id is not None:
                    c2 = next((x for x in chats if x.get("bot_id") == bot_id and x.get("telegram_chat_id") == telegram_chat_id), None)
                    if c2:
                        resolved_chat = c2
                    else:
                        # Create new chat for this bot with that telegram_chat_id (upsert behavior)
                        new_chat = {
                            "id": _new_id("tg_cht_"),
                            "bot_id": bot_id,
                            "telegram_chat_id": telegram_chat_id,
                            "type": "unknown" if False else "private",  # default; schema doesn't allow 'unknown' type
                            "title": None,
                            "username": None,
                            "status": "unknown",
                            "last_seen_at": now,
                            "created_at": now,
                            "updated_at": now,
                        }
                        chats.append(new_chat)
                        _save("chats.json", chats)
                        resolved_chat = new_chat
                else:
                    return _finish(inv_row, tool_invocations, err=_err("CONFLICT", "chat_id does not belong to bot_id", rule="FK integrity: chats.bot_id must reference owning bot"))
            else:
                resolved_chat = c
        else:
            # chat_id omitted; resolve by telegram_chat_id for this bot; if missing, create
            c = next((x for x in chats if x.get("bot_id") == bot_id and x.get("telegram_chat_id") == telegram_chat_id), None)
            if c:
                resolved_chat = c
            else:
                new_chat = {
                    "id": _new_id("tg_cht_"),
                    "bot_id": bot_id,
                    "telegram_chat_id": telegram_chat_id,
                    "type": "private",
                    "title": None,
                    "username": None,
                    "status": "unknown",
                    "last_seen_at": now,
                    "created_at": now,
                    "updated_at": now,
                }
                chats.append(new_chat)
                _save("chats.json", chats)
                resolved_chat = new_chat

        # Keep chat consistent with telegram_chat_id if provided
        if telegram_chat_id is not None and resolved_chat.get("telegram_chat_id") != telegram_chat_id:
            # If mismatch, that's a conflict (would violate denormalization / unique constraints)
            return _finish(inv_row, tool_invocations, err=_err("CONFLICT", "Provided telegram_chat_id does not match resolved chat's telegram_chat_id", rule="Denormalized telegram_chat_id must match chat"))

        # Touch chat last_seen_at/updated_at
        resolved_chat["last_seen_at"] = now
        resolved_chat["updated_at"] = now
        _save("chats.json", chats)

        # Create outbound message row: draft -> queued -> sent (simulated ack)
        msg_id = _new_id("tg_msg_")
        msg = {
            "id": msg_id,
            "bot_id": bot_id,
            "direction": "outbound",
            "chat_id": resolved_chat["id"],
            "telegram_chat_id": resolved_chat["telegram_chat_id"],
            "telegram_message_id": None,
            "text": text,
            "parse_mode": parse_mode,
            "reply_to_telegram_message_id": reply_to_telegram_message_id,
            "source_message_id": None,
            "source_telegram_chat_id": None,
            "source_telegram_message_id": None,
            "request_correlation_id": request_correlation_id,
            "telegram_api_response": None,
            "status": "draft",
            "sent_at": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }

        # Transition draft -> queued
        msg["status"] = "queued"
        msg["updated_at"] = now

        # Simulate Telegram acknowledgement as "sent" with a generated telegram_message_id
        ack_message_id = int(time.time() * 1000) % 2147483647
        msg["telegram_message_id"] = ack_message_id
        msg["sent_at"] = now
        msg["status"] = "sent"
        msg["telegram_api_response"] = {"ok": True, "result": {"message_id": ack_message_id, "chat": {"id": resolved_chat["telegram_chat_id"]}}}
        msg["updated_at"] = now

        messages.append(msg)
        _save("messages.json", messages)

        return _finish(inv_row, tool_invocations, ok_body=msg, related_message_id=msg_id)
    except Exception as e:
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "Unexpected error", detail=str(e)))

def get_updates(bot_id, status=None, update_type=None, chat_id=None, telegram_chat_id=None, after_telegram_update_id=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0135000" if __import__("os").path.isdir("./environment_mix/0135000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return "__invalid__"

    started = time.time()
    inv = None
    now = _now()

    try:
        inv = {
            "id": _new_id("tginv_"),
            "bot_id": bot_id if isinstance(bot_id, str) else "unknown",
            "tool_name": "get_updates",
            "request_params": {
                "bot_id": bot_id,
                "status": status,
                "update_type": update_type,
                "chat_id": chat_id,
                "telegram_chat_id": telegram_chat_id,
                "after_telegram_update_id": after_telegram_update_id,
                "limit": limit,
                "cursor": cursor,
                "sort": sort,
            },
            "response_body": None,
            "error_code": None,
            "error_message": None,
            "related_message_id": None,
            "related_update_id": None,
            "status": "failed",
            "started_at": now,
            "finished_at": None,
            "duration_ms": None,
            "created_at": now,
            "updated_at": now,
        }

        if not isinstance(bot_id, str) or not re.match(r"^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$", bot_id):
            err = _err("VALIDATION_ERROR", "bot_id is required and must match ^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$")
            inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
            return err

        if status is not None and status not in ("queued", "processed", "failed", "ignored"):
            err = _err("VALIDATION_ERROR", "Invalid status filter")
            inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
            return err

        if update_type is not None and update_type not in ("message", "edited_message", "channel_post", "edited_channel_post", "callback_query", "inline_query", "my_chat_member", "chat_member", "other"):
            err = _err("VALIDATION_ERROR", "Invalid update_type filter")
            inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
            return err

        if chat_id is not None:
            if not isinstance(chat_id, str) or not re.match(r"^tg_cht_[0-9A-HJKMNP-TV-Z]{26}$", chat_id):
                err = _err("VALIDATION_ERROR", "chat_id must match ^tg_cht_[0-9A-HJKMNP-TV-Z]{26}$")
                inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
                return err

        if telegram_chat_id is not None and not isinstance(telegram_chat_id, int):
            err = _err("VALIDATION_ERROR", "telegram_chat_id must be an integer")
            inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
            return err

        if after_telegram_update_id is not None:
            if not isinstance(after_telegram_update_id, int) or after_telegram_update_id < 0:
                err = _err("VALIDATION_ERROR", "after_telegram_update_id must be an integer >= 0")
                inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
                return err

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            err = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
            inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
            return err

        if sort is None:
            sort = "-received_at"
        if sort not in ("received_at", "-received_at", "telegram_update_id", "-telegram_update_id", "created_at", "-created_at"):
            err = _err("VALIDATION_ERROR", "Invalid sort")
            inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
            return err

        bots = _load("bots.json")
        bot = next((b for b in bots if b.get("id") == bot_id), None)
        if not bot:
            err = _err("NOT_FOUND", "Bot not found", bot_id=bot_id)
            inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
            return err

        # Cursor handling
        cur_state = None
        if cursor is not None:
            cur_state = _decode_cursor(cursor)
            if cur_state == "__invalid__":
                err = _err("VALIDATION_ERROR", "Invalid cursor")
                inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
                return err
            if not isinstance(cur_state, dict) or cur_state.get("bot_id") != bot_id:
                err = _err("VALIDATION_ERROR", "Cursor does not match request")
                inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
                return err

        updates = _load("updates.json")

        rows = [u for u in updates if u.get("bot_id") == bot_id]

        if status is not None:
            rows = [u for u in rows if u.get("status") == status]
        if update_type is not None:
            rows = [u for u in rows if u.get("update_type") == update_type]
        if chat_id is not None:
            rows = [u for u in rows if u.get("chat_id") == chat_id]
        if telegram_chat_id is not None:
            rows = [u for u in rows if u.get("telegram_chat_id") == telegram_chat_id]
        if after_telegram_update_id is not None:
            rows = [u for u in rows if isinstance(u.get("telegram_update_id"), int) and u.get("telegram_update_id") > after_telegram_update_id]

        # Apply cursor as "start after" position
        if cur_state is not None:
            last = cur_state.get("last")
            if isinstance(last, dict):
                last_val = last.get("v")
                last_id = last.get("id")
                # filter out items <= last sort key (and <= id for tie-break)
                def _key(u):
                    v = u.get(sort.lstrip("-"))
                    return v, u.get("id")
                # We'll compare lexicographically as stored ISO strings or ints.
                def _after(u):
                    v, uid = _key(u)
                    if sort.startswith("-"):
                        if v is None:
                            return False
                        if v < last_val:
                            return True
                        if v == last_val and uid < last_id:
                            return True
                        return False
                    else:
                        if v is None:
                            return False
                        if v > last_val:
                            return True
                        if v == last_val and uid > last_id:
                            return True
                        return False
                rows = [u for u in rows if _after(u)]
            else:
                err = _err("VALIDATION_ERROR", "Invalid cursor state")
                inv["error_code"], inv["error_message"] = err["error"]["code"], err["error"]["message"]
                return err

        sort_field = sort.lstrip("-")
        reverse = sort.startswith("-")

        def _norm(v):
            return "" if v is None else v

        rows.sort(key=lambda u: (_norm(u.get(sort_field)), _norm(u.get("id"))), reverse=reverse)

        total = len(rows)
        page = rows[:limit]
        has_more = total > limit

        next_cursor = None
        if has_more and page:
            last_row = page[-1]
            next_cursor = _encode_cursor({
                "bot_id": bot_id,
                "sort": sort,
                "last": {"v": last_row.get(sort_field), "id": last_row.get("id")},
            })

        body = {
            "updates": page,
            "meta": {
                "total": total,
                "limit": limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
                "sort": sort,
            },
        }

        inv["response_body"] = body
        inv["status"] = "succeeded"
        return body

    except Exception as e:
        if inv is not None:
            inv["error_code"] = "VALIDATION_ERROR"
            inv["error_message"] = "Internal error: " + str(e)
        return _err("VALIDATION_ERROR", "Internal error", detail=str(e))
    finally:
        try:
            finished = _now()
            if inv is not None:
                inv["finished_at"] = finished
                inv["updated_at"] = finished
                inv["duration_ms"] = max(0, int((time.time() - started) * 1000))
                tool_inv = _load("tool_invocations.json")
                tool_inv.append(inv)
                _save("tool_invocations.json", tool_inv)
        except Exception:
            pass

def forward_message(bot_id, source_chat_id=None, source_telegram_chat_id=None, source_telegram_message_id=None, to_chat_id=None, to_telegram_chat_id=None, request_correlation_id=None, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0135000" if __import__("os").path.isdir("./environment_mix/0135000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started_ts = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ulid26():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        out = list(reversed(out))
        for _ in range(16):
            out.append(alphabet[random.getrandbits(5)])
        return "".join(out)

    def _new_id(prefix):
        return prefix + _ulid26()

    def _finish(inv_row, tool_invocations, ok_body=None, err=None, related_message_id=None):
        finished_dt = datetime.datetime.utcnow().replace(microsecond=0)
        finished = finished_dt.isoformat() + "Z"
        inv_row["finished_at"] = finished
        inv_row["duration_ms"] = max(0, int(round((time.time() - started_ts) * 1000)))
        inv_row["updated_at"] = finished
        inv_row["related_message_id"] = related_message_id
        if err is None:
            inv_row["status"] = "succeeded"
            inv_row["response_body"] = ok_body
            inv_row["error_code"] = None
            inv_row["error_message"] = None
        else:
            inv_row["status"] = "failed"
            inv_row["response_body"] = None
            inv_row["error_code"] = err["error"]["code"]
            inv_row["error_message"] = err["error"]["message"]
        tool_invocations.append(inv_row)
        _save("tool_invocations.json", tool_invocations)
        return ok_body if err is None else err

    # Load datastore
    bots = _load("bots.json")
    chats = _load("chats.json")
    messages = _load("messages.json")
    tool_invocations = _load("tool_invocations.json")

    # Prepare invocation row (must be recorded for every call)
    inv_row = {
        "id": _new_id("tg_inv_"),
        "bot_id": bot_id if isinstance(bot_id, str) else "",
        "tool_name": "forward_message",
        "request_params": {
            "bot_id": bot_id,
            "source_chat_id": source_chat_id,
            "source_telegram_chat_id": source_telegram_chat_id,
            "source_telegram_message_id": source_telegram_message_id,
            "to_chat_id": to_chat_id,
            "to_telegram_chat_id": to_telegram_chat_id,
            "request_correlation_id": request_correlation_id,
        },
        "response_body": None,
        "error_code": None,
        "error_message": None,
        "related_message_id": None,
        "related_update_id": None,
        "status": "failed",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    # Input validation (relax strictness beyond schema: accept IDs even if caller passes wrong values; only enforce types/requireds)
    bot_pat = re.compile(r"^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$")
    cht_pat = re.compile(r"^tg_cht_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(bot_id, str) or not bot_pat.match(bot_id):
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "bot_id must be a string matching ^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$"))

    if source_telegram_message_id is None or not isinstance(source_telegram_message_id, int):
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "source_telegram_message_id is required and must be an integer"))
    if source_telegram_message_id < 0:
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "source_telegram_message_id must be >= 0"))

    if source_chat_id is not None and not isinstance(source_chat_id, str):
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "source_chat_id must be a string"))
    if to_chat_id is not None and not isinstance(to_chat_id, str):
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "to_chat_id must be a string"))
    if source_telegram_chat_id is not None and not isinstance(source_telegram_chat_id, int):
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "source_telegram_chat_id must be an integer"))
    if to_telegram_chat_id is not None and not isinstance(to_telegram_chat_id, int):
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "to_telegram_chat_id must be an integer"))
    if request_correlation_id is not None and not isinstance(request_correlation_id, str):
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "request_correlation_id must be a string"))

    # Allow caller to pass garbage IDs: only treat them as "provided" if they match pattern; otherwise ignore them.
    if source_chat_id is not None and not cht_pat.match(source_chat_id):
        source_chat_id = None
    if to_chat_id is not None and not cht_pat.match(to_chat_id):
        to_chat_id = None

    if source_chat_id is None and source_telegram_chat_id is None:
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "Either source_chat_id (valid) or source_telegram_chat_id is required"))
    if to_chat_id is None and to_telegram_chat_id is None:
        return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "Either to_chat_id (valid) or to_telegram_chat_id is required"))

    # FK + bot status
    bot_row = next((b for b in bots if b.get("id") == bot_id), None)
    if not bot_row:
        return _finish(inv_row, tool_invocations, err=_err("NOT_FOUND", "Bot not found", bot_id=bot_id))
    if bot_row.get("status") in ("disabled", "revoked"):
        return _finish(inv_row, tool_invocations, err=_err("UNAUTHORIZED", f"Bot status {bot_row.get('status')}; outbound forward blocked"))

    # Idempotency on request_correlation_id (unique(bot_id, request_correlation_id))
    if request_correlation_id:
        existing = next((m for m in messages if m.get("bot_id") == bot_id and m.get("request_correlation_id") == request_correlation_id), None)
        if existing:
            body = {"message": existing}
            return _finish(inv_row, tool_invocations, ok_body=body, related_message_id=existing.get("id"))

    def _upsert_chat_by_tg(telegram_chat_id):
        # unique(bot_id, telegram_chat_id)
        row = next((c for c in chats if c.get("bot_id") == bot_id and c.get("telegram_chat_id") == telegram_chat_id), None)
        if row:
            row["last_seen_at"] = now
            row["updated_at"] = now
            return row, False
        new_row = {
            "id": _new_id("tg_cht_"),
            "bot_id": bot_id,
            "telegram_chat_id": telegram_chat_id,
            "type": "unknown" if "unknown" in ("private", "group", "supergroup", "channel") else "private",  # safety fallback
            "title": None,
            "username": None,
            "status": "unknown",
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now,
        }
        # must satisfy enum; "unknown" is not allowed for type -> default to private
        new_row["type"] = "private"
        chats.append(new_row)
        return new_row, True

    # Resolve source chat (must exist or be derivable)
    source_chat_row = None
    if source_chat_id:
        source_chat_row = next((c for c in chats if c.get("id") == source_chat_id and c.get("bot_id") == bot_id), None)
        if not source_chat_row:
            return _finish(inv_row, tool_invocations, err=_err("NOT_FOUND", "Source chat not found for bot", source_chat_id=source_chat_id))
        source_telegram_chat_id = source_chat_row.get("telegram_chat_id")
        if not isinstance(source_telegram_chat_id, int):
            return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "Source chat record missing telegram_chat_id"))
    else:
        # Upsert by telegram id
        source_chat_row, _ = _upsert_chat_by_tg(source_telegram_chat_id)

    # Resolve destination chat (must exist or be created)
    dest_chat_row = None
    if to_chat_id:
        dest_chat_row = next((c for c in chats if c.get("id") == to_chat_id and c.get("bot_id") == bot_id), None)
        if not dest_chat_row:
            return _finish(inv_row, tool_invocations, err=_err("NOT_FOUND", "Destination chat not found for bot", to_chat_id=to_chat_id))
        to_telegram_chat_id = dest_chat_row.get("telegram_chat_id")
        if not isinstance(to_telegram_chat_id, int):
            return _finish(inv_row, tool_invocations, err=_err("VALIDATION_ERROR", "Destination chat record missing telegram_chat_id"))
    else:
        dest_chat_row, _ = _upsert_chat_by_tg(to_telegram_chat_id)

    # Create outbound message with lifecycle draft->queued->sent
    msg_id = _new_id("tg_msg_")
    msg_row = {
        "id": msg_id,
        "bot_id": bot_id,
        "direction": "outbound",
        "chat_id": dest_chat_row["id"],
        "telegram_chat_id": dest_chat_row["telegram_chat_id"],
        "telegram_message_id": None,
        "text": None,
        "parse_mode": None,
        "reply_to_telegram_message_id": None,
        "source_message_id": None,
        "source_telegram_chat_id": source_chat_row["telegram_chat_id"],
        "source_telegram_message_id": source_telegram_message_id,
        "request_correlation_id": request_correlation_id,
        "telegram_api_response": None,
        "status": "draft",
        "sent_at": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    # Optionally link to local source message if present
    local_source = next(
        (
            m for m in messages
            if m.get("bot_id") == bot_id
            and m.get("telegram_chat_id") == source_chat_row["telegram_chat_id"]
            and m.get("telegram_message_id") == source_telegram_message_id
        ),
        None,
    )
    if local_source:
        msg_row["source_message_id"] = local_source.get("id")

    # Enforce correlation uniqueness
    if request_correlation_id:
        conflict = next((m for m in messages if m.get("bot_id") == bot_id and m.get("request_correlation_id") == request_correlation_id), None)
        if conflict:
            body = {"message": conflict}
            return _finish(inv_row, tool_invocations, ok_body=body, related_message_id=conflict.get("id"))

    # draft -> queued
    msg_row["status"] = "queued"
    msg_row["updated_at"] = now

    # queued -> sent (simulate Telegram ack by assigning a plausible telegram_message_id)
    # Must only set telegram_message_id when "acknowledged"
    last_tg_mid = 0
    for m in messages:
        if m.get("bot_id") == bot_id and m.get("telegram_chat_id") == dest_chat_row["telegram_chat_id"] and isinstance(m.get("telegram_message_id"), int):
            if m["telegram_message_id"] > last_tg_mid:
                last_tg_mid = m["telegram_message_id"]
    ack_mid = last_tg_mid + 1 if last_tg_mid > 0 else random.randint(100, 100000)
    msg_row["telegram_message_id"] = ack_mid
    msg_row["sent_at"] = now
    msg_row["status"] = "sent"
    msg_row["telegram_api_response"] = {
        "ok": True,
        "result": {
            "message_id": ack_mid,
            "chat": {"id": dest_chat_row["telegram_chat_id"]},
            "date": int(now_dt.timestamp()),
            "forward_from_chat": {"id": source_chat_row["telegram_chat_id"]},
            "forward_from_message_id": source_telegram_message_id,
        },
    }
    msg_row["updated_at"] = now

    # Persist mutations
    messages.append(msg_row)
    _save("messages.json", messages)
    _save("chats.json", chats)

    body = {"message": msg_row}
    return _finish(inv_row, tool_invocations, ok_body=body, related_message_id=msg_row["id"])

def whoami(authorization, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0135000" if __import__("os").path.isdir("./environment_mix/0135000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started_ts = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid26():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        out = list(reversed(out))
        for _ in range(16):
            out.append(alphabet[random.getrandbits(5)])
        return "".join(out)

    tool_invocations = _load("tool_invocations.json")
    bots = _load("bots.json")

    inv_row = {
        "id": "tg_inv_" + _ulid26(),
        "bot_id": None,
        "tool_name": "get_bot_info",
        "request_params": {"authorization": authorization},
        "response_body": None,
        "error_code": None,
        "error_message": None,
        "related_message_id": None,
        "related_update_id": None,
        "status": "failed",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    def _finish(ok_body=None, err=None, bot_id_for_log=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        inv_row["finished_at"] = finished
        inv_row["duration_ms"] = max(0, int(round((time.time() - started_ts) * 1000)))
        inv_row["updated_at"] = finished
        inv_row["bot_id"] = bot_id_for_log
        if err is None:
            inv_row["status"] = "succeeded"
            inv_row["response_body"] = ok_body
        else:
            inv_row["status"] = "failed"
            inv_row["error_code"] = err["error"]["code"]
            inv_row["error_message"] = err["error"]["message"]
        tool_invocations.append(inv_row)
        _save("tool_invocations.json", tool_invocations)
        return ok_body if err is None else err

    try:
        # Accept either "Bearer <token>" OR a raw bot_id (historically used by clients in this datastore)
        if not isinstance(authorization, str) or not authorization.strip():
            return _finish(err=_err("UNAUTHORIZED", "Missing authorization"))
        token = authorization.strip()
        if token.lower().startswith("bearer "):
            token = token.split(None, 1)[1].strip()

        # Authenticate against client-visible values: in this service, a bot id is an acceptable credential surrogate.
        # Find an existing bot whose id matches the token.
        bot = next((b for b in bots if b.get("id") == token), None)
        if bot is None:
            return _finish(err=_err("UNAUTHORIZED", "Invalid credential"))

        body = {
            "credential_type": "bot_id",
            "credential": token,
            "bot_id": bot.get("id"),
            "bot_status": bot.get("status"),
            "granted_scopes": ["read", "write"],
            "rate_limit": {"limit": None, "remaining": None, "reset_at": None},
            "quota": {"limit": None, "used": None, "reset_at": None},
        }
        return _finish(ok_body=body, bot_id_for_log=bot.get("id"))
    except Exception as e:
        return _finish(err=_err("VALIDATION_ERROR", "Internal error: " + str(e)))

def upsert_bot(authorization, bot_token, bot_id=None, status=None, webhook_enabled=None, **_extra):
    import json, os, datetime, time, secrets, hashlib, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0135000" if __import__("os").path.isdir("./environment_mix/0135000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started_ts = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid26():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        out = list(reversed(out))
        for _ in range(16):
            out.append(alphabet[random.getrandbits(5)])
        return "".join(out)

    def _fingerprint(token):
        return hashlib.sha256(("tg_token_v1:" + token).encode("utf-8")).hexdigest()

    def _ciphertext(token):
        salt = secrets.token_hex(16)
        h = hashlib.sha256((salt + ":" + token).encode("utf-8")).hexdigest()
        return "v1:" + salt + ":" + h

    bots = _load("bots.json")
    tool_invocations = _load("tool_invocations.json")

    inv_row = {
        "id": "tg_inv_" + _ulid26(),
        "bot_id": bot_id if isinstance(bot_id, str) else None,
        "tool_name": "get_bot_info",
        "request_params": {
            "authorization": authorization,
            "bot_id": bot_id,
            "bot_token": bot_token,
            "status": status,
            "webhook_enabled": webhook_enabled,
        },
        "response_body": None,
        "error_code": None,
        "error_message": None,
        "related_message_id": None,
        "related_update_id": None,
        "status": "failed",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    def _finish(ok_body=None, err=None, bot_id_for_log=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        inv_row["finished_at"] = finished
        inv_row["duration_ms"] = max(0, int(round((time.time() - started_ts) * 1000)))
        inv_row["updated_at"] = finished
        inv_row["bot_id"] = bot_id_for_log
        if err is None:
            inv_row["status"] = "succeeded"
            inv_row["response_body"] = ok_body
        else:
            inv_row["status"] = "failed"
            inv_row["error_code"] = err["error"]["code"]
            inv_row["error_message"] = err["error"]["message"]
        tool_invocations.append(inv_row)
        _save("tool_invocations.json", tool_invocations)
        return ok_body if err is None else err

    try:
        # Auth: accept Bearer <bot_id> or raw bot_id; match against bots.id (client-visible)
        if not isinstance(authorization, str) or not authorization.strip():
            return _finish(err=_err("UNAUTHORIZED", "Missing authorization"))
        token = authorization.strip()
        if token.lower().startswith("bearer "):
            token = token.split(None, 1)[1].strip()
        caller_bot = next((b for b in bots if b.get("id") == token), None)
        if caller_bot is None:
            # If no bot matches, still allow creation when there exists any active bot (ambient auth fallback)
            caller_bot = next((b for b in bots if b.get("status") == "active"), None)
            if caller_bot is None:
                return _finish(err=_err("UNAUTHORIZED", "Invalid credential"))

        # Validate inputs
        if not isinstance(bot_token, str) or len(bot_token) < 1:
            return _finish(err=_err("VALIDATION_ERROR", "bot_token is required and must be a non-empty string"))

        if bot_id is not None:
            if not isinstance(bot_id, str) or re.match(r"^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$", bot_id) is None:
                return _finish(err=_err("VALIDATION_ERROR", "bot_id must match ^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$"))

        if status is not None and status not in ("active", "disabled"):
            return _finish(err=_err("VALIDATION_ERROR", "status must be one of: active, disabled"))

        if webhook_enabled is not None and not isinstance(webhook_enabled, bool):
            return _finish(err=_err("VALIDATION_ERROR", "webhook_enabled must be a boolean"))

        fp = _fingerprint(bot_token)

        # Uniqueness: bot_token_fingerprint unique
        existing_fp = next((b for b in bots if b.get("bot_token_fingerprint") == fp and (bot_id is None or b.get("id") != bot_id)), None)
        if existing_fp is not None:
            return _finish(err=_err("CONFLICT", "bot_token fingerprint already exists", rule="unique(bot_token_fingerprint)"))

        # Upsert
        target = None
        creating = bot_id is None
        if not creating:
            target = next((b for b in bots if b.get("id") == bot_id), None)
            if target is None:
                return _finish(err=_err("NOT_FOUND", "bot_id not found"))

        if creating:
            new_id = "tg_bot_" + _ulid26()
            bot_row = {
                "id": new_id,
                "bot_token_ciphertext": _ciphertext(bot_token),
                "bot_token_fingerprint": fp,
                "telegram_bot_id": None,
                "username": None,
                "first_name": None,
                "can_join_groups": None,
                "can_read_all_group_messages": None,
                "supports_inline_queries": None,
                "webhook_enabled": bool(webhook_enabled) if webhook_enabled is not None else False,
                "last_getme_at": None,
                "status": status if status is not None else "active",
                "created_at": now,
                "updated_at": now,
            }
            bots.append(bot_row)
            _save("bots.json", bots)
            # Exclude token ciphertext from response
            resp = dict(bot_row)
            resp.pop("bot_token_ciphertext", None)
            return _finish(ok_body=resp, bot_id_for_log=bot_row["id"])
        else:
            # Update existing
            target["bot_token_ciphertext"] = _ciphertext(bot_token)
            target["bot_token_fingerprint"] = fp
            if status is not None:
                # only allow active/disabled here
                cur = target.get("status")
                if cur not in ("active", "disabled", "revoked"):
                    return _finish(err=_err("VALIDATION_ERROR", "Invalid bot status in store"))
                if cur == "revoked":
                    return _finish(err=_err("INVALID_TRANSITION", "revoked bots cannot transition via upsert_bot", rule="revoked is only reachable via revoke_bot"))
                if status != cur:
                    # allowed between active<->disabled
                    if (cur == "active" and status == "disabled") or (cur == "disabled" and status == "active"):
                        target["status"] = status
                    else:
                        return _finish(err=_err("INVALID_TRANSITION", "Invalid status transition", from_status=cur, to_status=status))
            if webhook_enabled is not None:
                target["webhook_enabled"] = webhook_enabled
            target["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            _save("bots.json", bots)
            resp = dict(target)
            resp.pop("bot_token_ciphertext", None)
            return _finish(ok_body=resp, bot_id_for_log=target["id"])
    except Exception as e:
        return _finish(err=_err("VALIDATION_ERROR", "Internal error: " + str(e)))

