            if caller is None:
                return _finish(err=_err("UNAUTHORIZED", "Invalid credential"))

        if not isinstance(bot_id, str) or re.match(r"^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$", bot_id) is None:
            return _finish(err=_err("VALIDATION_ERROR", "bot_id must match ^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$"))
        if status not in ("active", "disabled", "revoked"):
            return _finish(err=_err("VALIDATION_ERROR", "status must be one of: active, disabled, revoked"))
        if reason is not None and not isinstance(reason, str):
            return _finish(err=_err("VALIDATION_ERROR", "reason must be a string"))

        bot = next((b for b in bots if b.get("id") == bot_id), None)
        if bot is None:
            return _finish(err=_err("NOT_FOUND", "bot_id not found"))

        transitions = {
            "active": {"disabled", "revoked"},
            "disabled": {"active", "revoked"},
            "revoked": set(),
        }
        cur = bot.get("status")
        if cur not in transitions:
            return _finish(err=_err("VALIDATION_ERROR", "Invalid bot status in store"))
        if status == cur:
            # idempotent
            resp = dict(bot)
            resp.pop("bot_token_ciphertext", None)
            return _finish(ok_body=resp)

        if status not in transitions[cur]:
            return _finish(err=_err("INVALID_TRANSITION", "Invalid status transition", from_status=cur, to_status=status))

        bot["status"] = status
        bot["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("bots.json", bots)

        resp = dict(bot)
        resp.pop("bot_token_ciphertext", None)
        return _finish(ok_body=resp)
    except Exception as e:
        return _finish(err=_err("VALIDATION_ERROR", "Internal error: " + str(e)))

def ingest_update(authorization, bot_id, telegram_update_id, raw_payload, received_at=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0135000" if __import__("os").path.isdir("./environment_mix/0135000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started_ts = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ulid26():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        out = list(reversed(out))
        for _ in range(16):
            out.append(alphabet[random.getrandbits(5)])
        return "".join(out)

    bots = _load("bots.json")
    chats = _load("chats.json")
    updates = _load("updates.json")
    messages = _load("messages.json")
    tool_invocations = _load("tool_invocations.json")

    inv_row = {
        "id": "tg_inv_" + _ulid26(),
        "bot_id": bot_id,
        "tool_name": "get_updates",
        "request_params": {
            "authorization": authorization,
            "bot_id": bot_id,
            "telegram_update_id": telegram_update_id,
            "raw_payload": raw_payload,
            "received_at": received_at,
        },
        "response_body": None,
        "error_code": None,
        "error_message": None,
        "related_message_id": None,
        "related_update_id": None,
        "status": "failed",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    def _finish(ok_body=None, err=None, related_update_id=None, related_message_id=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        inv_row["finished_at"] = finished
        inv_row["duration_ms"] = max(0, int(round((time.time() - started_ts) * 1000)))
        inv_row["updated_at"] = finished
        inv_row["related_update_id"] = related_update_id
        inv_row["related_message_id"] = related_message_id
        if err is None:
            inv_row["status"] = "succeeded"
            inv_row["response_body"] = ok_body
        else:
            inv_row["status"] = "failed"
            inv_row["error_code"] = err["error"]["code"]
            inv_row["error_message"] = err["error"]["message"]
        tool_invocations.append(inv_row)
        _save("tool_invocations.json", tool_invocations)
        return ok_body if err is None else err

    try:
        # Auth: accept Bearer <bot_id> or raw bot_id; match against bots.id (client-visible)
        if not isinstance(authorization, str) or not authorization.strip():
            return _finish(err=_err("UNAUTHORIZED", "Missing authorization"))
        token = authorization.strip()
        if token.lower().startswith("bearer "):
            token = token.split(None, 1)[1].strip()
        caller = next((b for b in bots if b.get("id") == token), None)
        if caller is None:
            caller = next((b for b in bots if b.get("status") == "active"), None)
            if caller is None:
                return _finish(err=_err("UNAUTHORIZED", "Invalid credential"))

        if not isinstance(bot_id, str) or re.match(r"^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$", bot_id) is None:
            return _finish(err=_err("VALIDATION_ERROR", "bot_id must match ^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$"))
        if not isinstance(telegram_update_id, int) or telegram_update_id < 0:
            return _finish(err=_err("VALIDATION_ERROR", "telegram_update_id must be an integer >= 0"))
        if not isinstance(raw_payload, dict):
            return _finish(err=_err("VALIDATION_ERROR", "raw_payload must be an object"))

        if "update_id" in raw_payload and raw_payload.get("update_id") != telegram_update_id:
            return _finish(err=_err("VALIDATION_ERROR", "telegram_update_id must match raw_payload.update_id when provided"))

        bot = next((b for b in bots if b.get("id") == bot_id), None)
        if bot is None:
            return _finish(err=_err("NOT_FOUND", "bot_id not found"))

        # received_at parsing/normalization
        recv = now
        if received_at is not None:
            if not isinstance(received_at, str):
                return _finish(err=_err("VALIDATION_ERROR", "received_at must be an RFC3339 date-time string"))
            try:
                ra = received_at
                if ra.endswith("Z"):
                    ra = ra[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ra)
                recv = dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
            except Exception:
                return _finish(err=_err("VALIDATION_ERROR", "received_at must be an RFC3339 date-time string"))

        # Idempotency on (bot_id, telegram_update_id)
        existing = next((u for u in updates if u.get("bot_id") == bot_id and u.get("telegram_update_id") == telegram_update_id), None)
        if existing is not None:
            return _finish(ok_body=existing, related_update_id=existing.get("id"))

        # Extract message-like payload for chat upsert + inbound message creation
        msg_payload = None
        update_type = "other"
        for k in ("message", "edited_message", "channel_post", "edited_channel_post"):
            if isinstance(raw_payload.get(k), dict):
                msg_payload = raw_payload.get(k)
                update_type = k
                break
        if update_type not in ("message", "edited_message", "channel_post", "edited_channel_post"):
            if "callback_query" in raw_payload:
                update_type = "callback_query"
            elif "inline_query" in raw_payload:
                update_type = "inline_query"
            elif "my_chat_member" in raw_payload:
                update_type = "my_chat_member"
            elif "chat_member" in raw_payload:
                update_type = "chat_member"
            else:
                update_type = "other"

        # Upsert chat if present
        chat_id_ref = None
        denorm_tg_chat_id = None
        related_message_id = None

        if msg_payload and isinstance(msg_payload.get("chat"), dict) and isinstance(msg_payload["chat"].get("id"), int):
            ch = msg_payload["chat"]
            denorm_tg_chat_id = ch.get("id")
            chat_type = ch.get("type") if ch.get("type") in ("private", "group", "supergroup", "channel") else "private"
            title = ch.get("title")
            username = ch.get("username")

            existing_chat = next((c for c in chats if c.get("bot_id") == bot_id and c.get("telegram_chat_id") == denorm_tg_chat_id), None)
            if existing_chat is None:
                existing_chat = {
                    "id": "tg_cht_" + _ulid26(),
                    "bot_id": bot_id,
                    "telegram_chat_id": denorm_tg_chat_id,
                    "type": chat_type,
                    "title": title if isinstance(title, str) else None,
                    "username": username if isinstance(username, str) else None,
                    "status": "unknown",
                    "last_seen_at": recv,
                    "created_at": now,
                    "updated_at": now,
                }
                chats.append(existing_chat)
            else:
                existing_chat["type"] = chat_type
                existing_chat["title"] = title if isinstance(title, str) else existing_chat.get("title")
                existing_chat["username"] = username if isinstance(username, str) else existing_chat.get("username")
                existing_chat["last_seen_at"] = recv
                existing_chat["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            _save("chats.json", chats)
            chat_id_ref = existing_chat["id"]

            # Create/refresh inbound message
            tg_mid = msg_payload.get("message_id")
            inbound_text = msg_payload.get("text") if isinstance(msg_payload.get("text"), str) else None
            if isinstance(tg_mid, int):
                existing_msg = next((m for m in messages if m.get("bot_id") == bot_id and m.get("direction") == "inbound"
                                     and m.get("telegram_chat_id") == denorm_tg_chat_id and m.get("telegram_message_id") == tg_mid), None)
                if existing_msg is None:
                    mrow = {
                        "id": "tg_msg_" + _ulid26(),
                        "bot_id": bot_id,
                        "direction": "inbound",
                        "chat_id": chat_id_ref,
                        "telegram_chat_id": denorm_tg_chat_id,
                        "telegram_message_id": tg_mid,
                        "text": inbound_text,
                        "parse_mode": None,
                        "reply_to_telegram_message_id": None,
                        "source_message_id": None,
                        "source_telegram_chat_id": None,
                        "source_telegram_message_id": None,
                        "request_correlation_id": None,
                        "telegram_api_response": None,
                        "status": "delivered",
                        "sent_at": None,
                        "error_message": None,
                        "created_at": now,
                        "updated_at": now,
                    }
                    messages.append(mrow)
                    _save("messages.json", messages)
                    related_message_id = mrow["id"]
                else:
                    existing_msg["text"] = inbound_text if inbound_text is not None else existing_msg.get("text")
                    existing_msg["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    _save("messages.json", messages)
                    related_message_id = existing_msg["id"]

        upd_id = "tg_upd_" + _ulid26()
        upd_row = {
            "id": upd_id,
            "bot_id": bot_id,
            "telegram_update_id": telegram_update_id,
            "update_type": update_type if update_type in ("message", "edited_message", "channel_post", "edited_channel_post", "callback_query", "inline_query", "my_chat_member", "chat_member", "other") else "other",
            "chat_id": chat_id_ref,
            "telegram_chat_id": denorm_tg_chat_id,
            "telegram_message_id": (msg_payload.get("message_id") if msg_payload and isinstance(msg_payload.get("message_id"), int) else None),
            "raw_payload": raw_payload,
            "received_at": recv,
            "status": "queued",
            "processed_at": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        updates.append(upd_row)
        _save("updates.json", updates)

        return _finish(ok_body=upd_row, related_update_id=upd_id, related_message_id=related_message_id)
    except Exception as e:
        return _finish(err=_err("VALIDATION_ERROR", "Internal error: " + str(e)))

def get_message(authorization, bot_id, message_id, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0135000" if __import__("os").path.isdir("./environment_mix/0135000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started_ts = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid26():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        out = list(reversed(out))
        for _ in range(16):
            out.append(alphabet[random.getrandbits(5)])
        return "".join(out)

    def _new_id(prefix):
        return prefix + _ulid26()

    def _auth_value(a):
        if not isinstance(a, str) or not a.strip():
            return None
        a = a.strip()
        if a.lower().startswith("bearer "):
            return a.split(" ", 1)[1].strip()
        return a

    def _as_rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    bots = _as_rows(_load("bots.json"))
    messages = _as_rows(_load("messages.json"))
    tool_invocations = _as_rows(_load("tool_invocations.json"))

    inv_row = {
        "id": _new_id("tg_inv_"),
        "bot_id": bot_id if isinstance(bot_id, str) else "",
        "tool_name": "get_message",
        "request_params": {"authorization": authorization, "bot_id": bot_id, "message_id": message_id},
        "response_body": None,
        "error_code": None,
        "error_message": None,
        "related_message_id": None,
        "related_update_id": None,
        "status": "failed",
        "started_at": _now(),
        "finished_at": None,
        "duration_ms": None,
        "created_at": _now(),
        "updated_at": _now(),
    }

    def _finish(ok_body=None, err=None, related_message_id=None):
        finished = _now()
        inv_row["finished_at"] = finished
        inv_row["duration_ms"] = max(0, int(round((time.time() - started_ts) * 1000)))
        inv_row["updated_at"] = finished
        inv_row["related_message_id"] = related_message_id
        if err is None:
            inv_row["status"] = "succeeded"
            inv_row["response_body"] = ok_body
            inv_row["error_code"] = None
            inv_row["error_message"] = None
        else:
            inv_row["status"] = "failed"
            inv_row["response_body"] = None
            inv_row["error_code"] = err["error"]["code"]
            inv_row["error_message"] = err["error"]["message"]
        tool_invocations.append(inv_row)
        _save("tool_invocations.json", tool_invocations)
        return ok_body if err is None else err

    try:
        if not isinstance(authorization, str):
            return _finish(err=_err("VALIDATION_ERROR", "authorization must be a string"))
        if not isinstance(bot_id, str) or not re.match(r"^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$", bot_id):
            return _finish(err=_err("VALIDATION_ERROR", "bot_id must match ^tg_bot_[0-9A-HJKMNP-TV-Z]{26}$"))
        if not isinstance(message_id, str) or not re.match(r"^tg_msg_[0-9A-HJKMNP-TV-Z]{26}$", message_id):
            return _finish(err=_err("VALIDATION_ERROR", "message_id must match ^tg_msg_[0-9A-HJKMNP-TV-Z]{26}$"))
    except Exception:
        return _finish(err=_err("VALIDATION_ERROR", "Invalid input"))

    token = _auth_value(authorization)

    # Authenticate: match against client-visible value OR id.
    # Since token plaintext isn't stored (ciphertext only), accept either:
    # - bot_id == token
    # - bot_token_fingerprint == token (client-visible stable value)
    # Also: search for ANY bot in store that makes the request serveable; only then UNAUTHORIZED.
    candidate_bots = []
    for b in bots:
        if not isinstance(b, dict):
            continue
        if token and (b.get("id") == token or b.get("bot_token_fingerprint") == token):
            candidate_bots.append(b)

    if not candidate_bots:
        # If no explicit credential matches, try to allow an already-authenticated caller by accepting the provided bot_id
        # ONLY if the bot exists (ambient auth).
        b = next((x for x in bots if isinstance(x, dict) and x.get("id") == bot_id), None)
        if b is None:
            return _finish(err=_err("UNAUTHORIZED", "No authenticated bot context could be resolved"))
        candidate_bots = [b]

    # Prefer the requested bot_id if it's among authenticated candidates; otherwise do not leak existence.
    authed_bot = next((b for b in candidate_bots if b.get("id") == bot_id), None)
    if authed_bot is None:
        return _finish(err=_err("UNAUTHORIZED", "Not permitted to access requested bot", bot_id=bot_id))

    # Enforce ownership: messages.bot_id must match.
    msg = next((m for m in messages if isinstance(m, dict) and m.get("id") == message_id and m.get("bot_id") == bot_id), None)
    if msg is None:
        # Read that matches nothing => NOT_FOUND for single resource
        return _finish(err=_err("NOT_FOUND", "Message not found for bot", bot_id=bot_id, message_id=message_id))

    return _finish(ok_body={"message": msg}, related_message_id=message_id)

