            break
    if upd_idx is None:
        return _finish(err=_err("NOT_FOUND", "Update not found for bot", bot_id=bot_id, update_id=update_id))

    upd = updates[upd_idx]
    cur = upd.get("status")
    transitions = {
        "queued": ("processed", "failed", "ignored"),
        "failed": ("queued", "ignored"),
        "processed": (),
        "ignored": (),
    }
    if cur not in transitions:
        return _finish(err=_err("VALIDATION_ERROR", "Persisted update has invalid current status", current_status=cur))

    if status == cur:
        # Idempotent: no mutation needed, but still "succeeded" with same record.
        return _finish(ok_body={"update": upd}, related_update_id=update_id)

    if status not in transitions[cur]:
        return _finish(
            err=_err(
                "INVALID_TRANSITION",
                f"Illegal status transition for updates: {cur} -> {status} (allowed: {list(transitions[cur])})",
                current_status=cur,
                target_status=status,
            ),
            related_update_id=update_id,
        )

    # Apply transition, enforce error_message rule for failed (optional but sensible)
    changed = False
    upd["status"] = status
    changed = True
    if status == "failed":
        if error_message:
            upd["error_message"] = error_message
        elif upd.get("error_message") is None:
            upd["error_message"] = "Update marked failed"
    else:
        # Clear error_message when leaving failed (keep if set historically? real services vary; we'll clear to reflect state)
        upd["error_message"] = None

    if status in ("processed", "failed", "ignored"):
        upd["processed_at"] = _now() if status != "queued" else upd.get("processed_at")
    if status == "queued":
        upd["processed_at"] = None

    if changed:
        upd["updated_at"] = _now()
        updates[upd_idx] = upd
        _save("updates.json", updates)
        return _finish(ok_body={"update": upd}, related_update_id=update_id)

    return _finish(err=_err("NOT_FOUND", "No update was modified", bot_id=bot_id, update_id=update_id), related_update_id=update_id)
